#!/usr/bin/env python3
import sys, re, threading
sys.set_int_max_str_digits(0)

class PErr(Exception): pass
class TErr(Exception): pass
class RErr(Exception): pass

INT, BOOL, VAR, LAM, APP, BIN, IF, LET, LETREC, ANNO = range(10)
KW = {'let', 'rec', 'in', 'if', 'then', 'else'}
RESERVED = {'match', 'with', 'type', 'forall'}
TOK = re.compile(r'[ \t\n\r\f\v]+|--[^\n]*|(\d+)|([a-z_][A-Za-z0-9_]*)|([A-Z][A-Za-z0-9_]*)|(->|//|==|[()/+\-*%<=:])')

def lex(src):
    toks = []
    pos = 0; n = len(src)
    m_ = TOK.match
    while pos < n:
        m = m_(src, pos)
        if not m: raise PErr('bad char')
        pos = m.end()
        if m.group(1) is not None: toks.append(('int', int(m.group(1))))
        elif m.group(2) is not None:
            s = m.group(2)
            if s == '_' or s in RESERVED: raise PErr('reserved')
            toks.append((s, None) if s in KW else ('id', s))
        elif m.group(3) is not None:
            s = m.group(3)
            if s not in ('True', 'False', 'Int', 'Bool'): raise PErr('upper')
            toks.append((s, None))
        elif m.group(4) is not None:
            toks.append((m.group(4), None))
    toks.append(('eof', None))
    return toks

class Parser:
    def __init__(s, toks): s.t = toks; s.i = 0
    def peek(s): return s.t[s.i][0]
    def eat(s, k):
        tk = s.t[s.i]
        if tk[0] != k: raise PErr('expected ' + k)
        s.i += 1
        return tk[1]
    def program(s):
        e = s.expr(); s.eat('eof'); return e
    def expr(s):
        k = s.peek()
        if k == '/':
            s.i += 1; x = s.eat('id'); s.eat('->'); b = s.expr()
            return [LAM, x, b, None]
        if k == 'let':
            s.i += 1
            if s.peek() == 'rec':
                s.i += 1; f = s.eat('id'); s.eat(':'); T = s.type_(); s.eat('=')
                e1 = s.expr()
                if e1[0] != LAM: raise PErr('let rec needs lambda')
                s.eat('in'); e2 = s.expr()
                return (LETREC, f, e1, e2, T)
            x = s.eat('id'); T = None
            if s.peek() == ':':
                s.i += 1; T = s.type_()
            s.eat('='); e1 = s.expr(); s.eat('in'); e2 = s.expr()
            if T is not None: e1 = (ANNO, e1, T)
            return (LET, x, e1, e2)
        if k == 'if':
            s.i += 1; c = s.expr(); s.eat('then'); a = s.expr(); s.eat('else'); b = s.expr()
            return (IF, c, a, b)
        return s.cmp()
    def cmp(s):
        l = s.add()
        k = s.peek()
        if k == '==' or k == '<':
            s.i += 1; r = s.add()
            l = (BIN, k, l, r)
            if s.peek() in ('==', '<'): raise PErr('nonassoc')
        return l
    def add(s):
        l = s.mul()
        while s.peek() in ('+', '-'):
            k = s.peek(); s.i += 1; l = (BIN, k, l, s.mul())
        return l
    def mul(s):
        l = s.app()
        while s.peek() in ('*', '//', '%'):
            k = s.peek(); s.i += 1; l = (BIN, k, l, s.app())
        return l
    ATOM_START = {'id', 'int', 'True', 'False', '('}
    def app(s):
        f = s.atom()
        while s.peek() in Parser.ATOM_START:
            f = (APP, f, s.atom())
        return f
    def atom(s):
        k, v = s.t[s.i]
        if k == 'id': s.i += 1; return (VAR, v)
        if k == 'int': s.i += 1; return (INT, v)
        if k == 'True': s.i += 1; return (BOOL, True)
        if k == 'False': s.i += 1; return (BOOL, False)
        if k == '(':
            s.i += 1; e = s.expr()
            if s.peek() == ':':
                s.i += 1; T = s.type_(); s.eat(')'); return (ANNO, e, T)
            s.eat(')'); return e
        raise PErr('unexpected ' + k)
    def type_(s):
        k = s.peek()
        if k == 'Int': s.i += 1; a = 'Int'
        elif k == 'Bool': s.i += 1; a = 'Bool'
        elif k == '(':
            s.i += 1; a = s.type_(); s.eat(')')
        else: raise PErr('type')
        if s.peek() == '->':
            s.i += 1; return ('->', a, s.type_())
        return a

# ---------- free variables ----------
def fv(e):
    t = e[0]
    if t == VAR: return {e[1]}
    if t == INT or t == BOOL: return set()
    if t == LAM:
        r = fv(e[2]); r.discard(e[1]); e[3] = tuple(r); return set(r)
    if t == APP: return fv(e[1]) | fv(e[2])
    if t == BIN: return fv(e[2]) | fv(e[3])
    if t == IF: return fv(e[1]) | fv(e[2]) | fv(e[3])
    if t == LET:
        r = fv(e[3]); r.discard(e[1]); return fv(e[2]) | r
    if t == LETREC:
        r = fv(e[2]) | fv(e[3]); r.discard(e[1]); return r
    if t == ANNO: return fv(e[1])

# ---------- types ----------
class TV:
    __slots__ = ('ref',)
    def __init__(s): s.ref = None

def prune(t):
    while isinstance(t, TV) and t.ref is not None: t = t.ref
    return t

def occurs(v, t):
    stack = [t]
    while stack:
        t = prune(stack.pop())
        if t is v: return True
        if isinstance(t, tuple): stack.append(t[1]); stack.append(t[2])
    return False

def unify(a, b):
    stack = [(a, b)]
    while stack:
        a, b = stack.pop()
        a = prune(a); b = prune(b)
        if a is b: continue
        if isinstance(a, TV):
            if occurs(a, b): raise TErr('occurs')
            a.ref = b; continue
        if isinstance(b, TV):
            if occurs(b, a): raise TErr('occurs')
            b.ref = a; continue
        if isinstance(a, str) or isinstance(b, str):
            if a != b: raise TErr('mismatch')
            continue
        stack.append((a[1], b[1])); stack.append((a[2], b[2]))

MISSING = object()
def infer(e, env):
    t = e[0]
    if t == INT: return 'Int'
    if t == BOOL: return 'Bool'
    if t == VAR:
        r = env.get(e[1])
        if r is None: raise TErr('unbound ' + e[1])
        return r
    if t == LAM:
        a = TV(); x = e[1]
        old = env.get(x, MISSING); env[x] = a
        try: b = infer(e[2], env)
        finally:
            if old is MISSING: del env[x]
            else: env[x] = old
        return ('->', a, b)
    if t == APP:
        f = prune(infer(e[1], env))
        if isinstance(f, TV):
            a = TV(); b = TV(); unify(f, ('->', a, b)); f = ('->', a, b)
        if not isinstance(f, tuple): raise TErr('not a function')
        unify(f[1], infer(e[2], env))
        return f[2]
    if t == BIN:
        unify(infer(e[2], env), 'Int'); unify(infer(e[3], env), 'Int')
        return 'Bool' if e[1] in ('==', '<') else 'Int'
    if t == IF:
        unify(infer(e[1], env), 'Bool')
        a = infer(e[2], env); unify(a, infer(e[3], env)); return a
    if t == ANNO:
        unify(infer(e[1], env), e[2]); return e[2]
    if t == LET or t == LETREC:
        x = e[1]
        if t == LET:
            a = infer(e[2], env)
        old = env.get(x, MISSING)
        try:
            if t == LETREC:
                env[x] = e[4]; unify(infer(e[2], env), e[4])
            else:
                env[x] = a
            return infer(e[3], env)
        finally:
            if old is MISSING: del env[x]
            else: env[x] = old

# ---------- evaluation ----------
class Clo:
    __slots__ = ('x', 'body', 'env')
    def __init__(s, x, body, env): s.x = x; s.body = body; s.env = env

def ev(e, env):
    while True:
        t = e[0]
        if t == VAR: return env[e[1]]
        if t == APP:
            f = ev(e[1], env)
            a = ev(e[2], env)
            env = f.env.copy(); env[f.x] = a; e = f.body
            continue
        if t == BIN:
            l = ev(e[2], env); r = ev(e[3], env); op = e[1]
            if op == '+': return l + r
            if op == '-': return l - r
            if op == '*': return l * r
            if op == '<': return l < r
            if op == '==': return l == r
            if r == 0: raise RErr('division by zero')
            if op == '//': return l // r
            return l % r
        if t == INT or t == BOOL: return e[1]
        if t == IF:
            e = e[2] if ev(e[1], env) else e[3]
            continue
        if t == LAM:
            return Clo(e[1], e[2], {v: env[v] for v in e[3]})
        if t == LET:
            v = ev(e[2], env)
            env = env.copy(); env[e[1]] = v; e = e[3]
            continue
        if t == LETREC:
            lam = e[2]; f = e[1]
            cenv = {v: env[v] for v in lam[3] if v != f}
            c = Clo(lam[1], lam[2], cenv); cenv[f] = c
            env = env.copy(); env[f] = c; e = e[3]
            continue
        if t == ANNO:
            e = e[1]; continue

def show(v):
    if v is True: return 'True'
    if v is False: return 'False'
    if isinstance(v, Clo): return '<function>'
    return str(v)

def main():
    out = None; code = 1
    try:
        try:
            with open(sys.argv[2], 'rb') as fh: data = fh.read()
            try: src = data.decode('ascii')
            except UnicodeDecodeError: raise PErr('non-ascii')
            ast = Parser(lex(src)).program()
        except (PErr, RecursionError) as ex:
            out = 'ParseError'; return
        try:
            fv(ast)
            infer(ast, {})
        except (TErr, RecursionError):
            out = 'TypeError'; return
        try:
            v = ev(ast, {})
        except RErr:
            out = 'RuntimeError'; return
        out = show(v); code = 0
    finally:
        res[0] = (out, code)

res = [('RuntimeError', 1)]
if __name__ == '__main__':
    sys.setrecursionlimit(10**7)
    threading.stack_size(1024 * 1024 * 1024)
    th = threading.Thread(target=main); th.start(); th.join()
    out, code = res[0]
    sys.stdout.write((out or 'RuntimeError') + '\n'); sys.stdout.flush()
    sys.exit(code)
